(function(){"use strict";function ease(t){return 1-Math.pow(1-t,3);}
function animateCount(el){var to=parseInt(el.getAttribute("data-to")||"0",10);var duration=parseInt(el.getAttribute("data-duration")||"0",10);if(!duration||duration<=0||!to){el.textContent=String(to);return;}
var start=performance.now();function frame(now){var t=Math.min(1,(now-start)/duration);var v=Math.round(ease(t)*to);el.textContent=String(v);if(t<1)requestAnimationFrame(frame);}
requestAnimationFrame(frame);}
function initCountUps(){var nodes=document.querySelectorAll(".count-up");for(var i=0;i<nodes.length;i++)animateCount(nodes[i]);}
function initChartTooltip(){var chart=document.querySelector(".chart");var tip=document.getElementById("chart-tip");var tipDay=document.getElementById("tip-day");var tipN=document.getElementById("tip-n");var tipPlural=document.getElementById("tip-plural");if(!chart||!tip||!tipDay||!tipN)return;var wrap=chart.parentElement;var pts=chart.querySelectorAll(".pt");function onMove(evt){var rect=chart.getBoundingClientRect();var x=evt.clientX-rect.left;var bestI=-1;var bestD=Infinity;for(var i=0;i<pts.length;i++){var p=pts[i].getBoundingClientRect();var cx=p.left+p.width/2-rect.left;var d=Math.abs(cx-x);if(d<bestD){bestD=d;bestI=i;}}
if(bestI<0){tip.classList.remove("is-on");for(var j=0;j<pts.length;j++)pts[j].classList.remove("pt-hover");return;}
for(var k=0;k<pts.length;k++)pts[k].classList.remove("pt-hover");pts[bestI].classList.add("pt-hover");var day=pts[bestI].getAttribute("data-day")||"";var nRaw=pts[bestI].getAttribute("data-n")||"0";var n=parseInt(nRaw,10);tipDay.textContent=day;tipN.textContent=n;if(tipPlural)tipPlural.textContent=n===1?"":"s";var wrapRect=wrap.getBoundingClientRect();var pRect=pts[bestI].getBoundingClientRect();var px=(pRect.left+pRect.width/2)-wrapRect.left;var py=(pRect.top)-wrapRect.top;tip.style.left=px+"px";tip.style.top=py+"px";tip.classList.add("is-on");}
function onLeave(){tip.classList.remove("is-on");for(var i=0;i<pts.length;i++)pts[i].classList.remove("pt-hover");}
chart.addEventListener("mousemove",onMove);chart.addEventListener("mouseleave",onLeave);}
function openModal(modal){if(!modal)return;modal.classList.add("is-open");modal.setAttribute("aria-hidden","false");}
function closeModal(modal){if(!modal)return;modal.classList.remove("is-open");modal.setAttribute("aria-hidden","true");}
function initSidebarToggle(){var btn=document.getElementById("sidebar-toggle");var sidebar=document.querySelector(".sidebar");if(!btn||!sidebar)return;btn.addEventListener("click",function(){sidebar.classList.toggle("is-open");});document.addEventListener("click",function(e){if(!sidebar.classList.contains("is-open"))return;if(sidebar.contains(e.target)||btn.contains(e.target))return;sidebar.classList.remove("is-open");});}
function initSearchSubmit(){var search=document.getElementById("search");if(!search)return;search.addEventListener("keydown",function(e){if(e.key==="Enter"){var q=encodeURIComponent(search.value||"");window.location.href="/admin/signups?q="+q;}});}
function initConfirmForms(){document.addEventListener("submit",function(e){var form=e.target;if(!form||form.tagName!=="FORM")return;var msg=form.getAttribute("data-confirm");if(msg&&!window.confirm(msg)){e.preventDefault();e.stopImmediatePropagation();}},true);}
function initKeyboard(){var modal=document.getElementById("kbd-modal");var toggle=document.getElementById("kbd-toggle");if(toggle&&modal){toggle.addEventListener("click",function(){openModal(modal);});}
var backdropClick=modal&&modal.addEventListener("mousedown",function(e){if(e.target===modal)closeModal(modal);});function rowNav(dir){var rows=document.querySelectorAll(".table tbody tr");if(!rows.length)return;var cur=document.querySelector(".table tbody tr.is-focus");var idx=0;if(cur){for(var i=0;i<rows.length;i++){if(rows[i]===cur){idx=i;break;}}
rows[idx].classList.remove("is-focus");idx+=dir;if(idx<0)idx=0;if(idx>=rows.length)idx=rows.length-1;}
rows[idx].classList.add("is-focus");rows[idx].scrollIntoView({block:"nearest"});}
document.addEventListener("keydown",function(e){var tag=(e.target&&e.target.tagName)||"";var editable=tag==="INPUT"||tag==="TEXTAREA"||tag==="SELECT"||(e.target&&e.target.isContentEditable);if(modal&&modal.classList.contains("is-open")){if(e.key==="Escape"){closeModal(modal);e.preventDefault();}
return;}
if(editable)return;var k=e.key;if(k==="?"){if(modal)openModal(modal);e.preventDefault();return;}
if(k==="Escape"){closeModal(modal);return;}
if(k==="/"||(e.metaKey&&k.toLowerCase()==="k")||(e.ctrlKey&&k.toLowerCase()==="k")){var search=document.getElementById("search")||document.getElementById("q");if(search){search.focus();search.select&&search.select();e.preventDefault();}
return;}
if(k==="j"){rowNav(1);e.preventDefault();return;}
if(k==="k"){rowNav(-1);e.preventDefault();return;}
if(k==="d"){window.location.href="/admin/";return;}
if(k==="s"){window.location.href="/admin/signups";return;}
if(k==="a"){window.location.href="/admin/audit";return;}
if(k==="e"){window.location.href="/admin/signups/export.csv";return;}});}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init);}else{init();}
function init(){initCountUps();initChartTooltip();initSidebarToggle();initSearchSubmit();initConfirmForms();initKeyboard();}})();